const patternData={dots:{title:"Bindi (Dots) Pattern",desc:"Symbolizes life energy, stars, and seeds of creation. Used by Gond artists to create glowing texture across animal bodies."},lines:{title:"Rekha (Fine Lines) Pattern",desc:"Represents flow, movement, and life currents. Parrallel lines give rhythm to trees, rivers, and bird feathers."},waves:{title:"Lahar (Wavy Curves) Pattern",desc:"Inspired by flowing water streams and wind ripples across grass, bringing motion to nature storytelling."},drops:{title:"Beej (Seed Drops) Pattern",desc:"Represents fertility, monsoon raindrops, and forest blossoms. Each droplet anchors sacred animal figures."}};function initTheme(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const t=document.body.classList.contains("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"☀️":"🌙"})}function initNavTabs(){const e=document.querySelectorAll(".gond-tab-link");window.addEventListener("scroll",()=>{let t="";document.querySelectorAll(".gond-section").forEach(e=>{const n=e.offsetTop-100;window.scrollY>=n&&(t=e.getAttribute("id"))}),e.forEach(e=>{e.classList.remove("active"),e.getAttribute("href")===`#${t}`&&e.classList.add("active")})})}function initPatternVisualizer(){const e=document.querySelectorAll(".pattern-btn"),t=document.getElementById("pattern-preview");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),n.classList.add("active");const r=n.getAttribute("data-pattern"),s=patternData[r];s&&t&&(t.innerHTML=`\n          <h4>${s.title}</h4>\n          <p>${s.desc}</p>\n        `)})})}function initBookmark(){const e=document.querySelector(".gond-bookmark-btn");e&&e.addEventListener("click",()=>{const t="true"===e.getAttribute("aria-pressed");e.setAttribute("aria-pressed",!t),e.innerHTML=t?"♡ Save to Journey":"♥ Saved in Journey",e.style.background=t?"transparent":"var(--gond-accent)",e.style.color=t?"var(--gond-accent)":"#0f172a"})}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavTabs(),initPatternVisualizer(),initBookmark()});